        public static readonly IReadOnlyList<NativeActionDefinition> All = Array.AsReadOnly(Signatures.Select(Parse).ToArray());
        public static NativeActionDefinition? Find(string id) => All.FirstOrDefault(d => d.Id == id);
        private static NativeActionDefinition Parse(string row)
        {
            var fields = row.Split('|');
            return new NativeActionDefinition { Id = fields[0], Type = fields[1], Method = fields[2], ReturnType = fields[3],
                Parameters = fields.Skip(4).Select(field =>
                {
                    var direction = field.Split('!'); var value = direction[0].Split('=');
                    int space = value[0].LastIndexOf(' ');
                    return new NativeActionParameter { Type = value[0].Substring(0, space), Name = value[0].Substring(space + 1),
                        Default = value.Length > 1 ? value[1] : "", Direction = direction.Length > 1 ? direction[1] : "" };
                }).ToArray() };
        }
    }
